from collections import deque

def transform(grid):
    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    outside=set()
    q=deque()
    for r in range(h):
        for c in (0,w-1):
            if grid[r][c]==0 and (r,c) not in outside:
                outside.add((r,c)); q.append((r,c))
    for c in range(w):
        for r in (0,h-1):
            if grid[r][c]==0 and (r,c) not in outside:
                outside.add((r,c)); q.append((r,c))
    while q:
        r,c=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<h and 0<=nc<w and grid[nr][nc]==0 and (nr,nc) not in outside:
                outside.add((nr,nc)); q.append((nr,nc))
    inside={(r,c) for r in range(h) for c in range(w) if grid[r][c]==0 and (r,c) not in outside}
    # Identify 8-connected components of 1s that border enclosed zeros.
    ones={(r,c) for r in range(h) for c in range(w) if grid[r][c]==1}
    active=set(); seen=set()
    for p in ones:
        if p in seen: continue
        comp={p}; seen.add(p); q=deque([p])
        while q:
            r,c=q.popleft()
            for dr in (-1,0,1):
                for dc in (-1,0,1):
                    if not (dr or dc): continue
                    n=(r+dr,c+dc)
                    if n in ones and n not in seen:
                        seen.add(n); comp.add(n); q.append(n)
        if any((r+dr,c+dc) in inside for r,c in comp for dr in (-1,0,1) for dc in (-1,0,1)):
            active |= comp
    # color only the one-cell 8-neighbor rims on each side
    for r,c in inside:
        if any((r+dr,c+dc) in ones for dr in (-1,0,1) for dc in (-1,0,1)):
            out[r][c]=3
    for r,c in outside:
        if any((r+dr,c+dc) in active for dr in (-1,0,1) for dc in (-1,0,1)):
            out[r][c]=2
    return out

